"""
Evaluation metrics for tensor quantization fidelity.
"""
import numpy as np

def compute_mse(original: np.ndarray, quantized: np.ndarray) -> float:
    """Calculates Mean Squared Error between original and reconstructed tensor."""
    return float(np.mean((original.astype(np.float64) - quantized.astype(np.float64)) ** 2))

def compute_snr_db(original: np.ndarray, quantized: np.ndarray) -> float:
    """Calculates Signal-to-Noise Ratio (SNR) in decibels (dB)."""
    signal_power = np.mean(original.astype(np.float64) ** 2)
    noise_power = np.mean((original.astype(np.float64) - quantized.astype(np.float64)) ** 2)
    if noise_power == 0:
        return float('inf')
    return float(10.0 * np.log10(signal_power / noise_power))

def compute_cosine_similarity(a: np.ndarray, b: np.ndarray) -> float:
    """Computes cosine similarity between flattened tensors."""
    flat_a = a.flatten().astype(np.float64)
    flat_b = b.flatten().astype(np.float64)
    norm_a = np.linalg.norm(flat_a)
    norm_b = np.linalg.norm(flat_b)
    if norm_a == 0 or norm_b == 0:
        return 0.0
    return float(np.dot(flat_a, flat_b) / (norm_a * norm_b))
